import {test,expect} from '@playwright/test';
import {randomUUID} from 'node:crypto';
import {openWorkspaceSwitcher,returnToDiverWorkspace} from './portal-test-helpers.js';
const json=(route,body,status=200)=>route.fulfill({status,contentType:'application/json',body:JSON.stringify(body)});
const now='2026-10-22T19:00:00.000Z';
const agent=(key,nameAr,state='PAUSED')=>({key,nameAr,state,revision:randomUUID(),departmentName:'التشغيل',allowedActions:['READ_OPERATIONS','DRAFT_REPORT'],counts:{running:0,queued:0,overdue:0,failed:0},workload:'AVAILABLE',canEnable:true});
const task=(extra={})=>({id:randomUUID(),revision:randomUUID(),state:'QUEUED',action:'DRAFT_REPORT',language:'ar-SA',prompt:'موجز مهمة اختبار',createdAt:now,estimatedCostMicroUsd:null,result:null,approvalRequired:true,...extra});
const governanceKeys=['GOV_QUALITY_AUDIT','GOV_TECH_REVIEW','GOV_SECURITY_RISK','GOV_COMPLIANCE_POLICY','GOV_VERIFICATION','GOV_FINAL_GATE'];
async function setup(page,options={}){
 const state={catalogReads:0,failCatalog:false,inboxFiles:[],inboxOlder:[],inboxNext:null,inboxDetails:{},inboxReads:0,delayInboxDetail:false,releaseInboxDetail:null,admin:true,ready:true,items:[agent('INVENTORY','وكيل المخزون'),agent('SUPPORT','وكيل الدعم','ENABLED')],tasks:[],writes:[],connectionChecks:0,connectionResponse:{connected:true,reason:'MODEL_ACCESS_VERIFIED',provider:'OPENAI',model:'fixture-model',checkedAt:now,scope:'MODEL_ACCESS_ONLY',generationTested:false},delayConnection:false,releaseConnection:null,failQueue:false,failControl:false,delay:false,release:null,pages:false,...options};
 await page.route('**/api/v1/**',r=>json(r,[]));await page.route('**/auth/google/config',r=>json(r,{enabled:false}));
 await page.route(/\/api\/v1\/me$/,r=>json(r,{id:'agent-browser-admin',status:'ACTIVE',person:{firstName:'إدارة',lastName:'اختبار'},roleAssignments:state.admin?[{role:'ADMIN',status:'ACTIVE'}]:[]}));
 await page.route(/\/admin\/employees(?:\?.*)?$/,r=>json(r,{initialized:true,departments:[],profiles:[],items:[],nextCursor:null,email:{enabled:false},google:{enabled:false}}));
 await page.route(/\/admin\/agents$/,async r=>{state.catalogReads++;if(state.failCatalog)return json(r,{message:'تعذر قراءة حالة الوكلاء.'},503);if(state.delay)await new Promise(resolve=>state.release=resolve);return json(r,{initialized:true,provider:{ready:state.ready,reason:state.ready?'READY':'CREDENTIALS_MISSING',model:state.ready?'fixture-model':null,rateControl:state.rateControl||null},observedAt:new Date().toISOString(),workerObservedAt:state.ready?new Date().toISOString():null,metricsMaxAgeSeconds:90,budget:{limitMicroUsd:1000000,reservedMicroUsd:0,taskReserveMicroUsd:2560,day:'2026-10-22'},items:state.items.map(a=>({...a,canEnable:state.ready,counts:state.ready?a.counts:null,workload:state.ready?a.workload:'UNAVAILABLE'}))});});
 await page.route(/\/admin\/agents\/governance-reviews(?:\?.*)?$/,r=>{state.inboxReads++;return json(r,{scope:'ADVISORY_RUNTIME_OUTPUTS',readOnly:true,items:new URL(r.request().url()).searchParams.has('cursor')?state.inboxOlder:state.inboxFiles,nextCursor:new URL(r.request().url()).searchParams.has('cursor')?null:state.inboxNext});});
 await page.route('**/admin/agents/governance-reviews/*',async r=>{state.inboxReads++;if(state.delayInboxDetail)await new Promise(resolve=>state.releaseInboxDetail=resolve);return json(r,state.inboxDetails[new URL(r.request().url()).pathname.split('/').at(-1)]);});
 await page.route('**/admin/agents/provider-connection',async r=>{expect(r.request().method()).toBe('GET');state.connectionChecks++;if(state.delayConnection)await new Promise(resolve=>state.releaseConnection=resolve);return json(r,state.connectionResponse);});
 await page.route('**/admin/agents/*/control',r=>{const body=r.request().postDataJSON(),key=new URL(r.request().url()).pathname.split('/').at(-2);state.writes.push({kind:'control',key,body});if(state.failControl)return json(r,{message:'تغيرت الحالة؛ حدّث الوكلاء وراجع الإجراء.'},409);const a=state.items.find(a=>a.key===key);Object.assign(a,{state:body.state,revision:randomUUID()});return json(r,{key,state:a.state,revision:a.revision});});
 await page.route(/\/admin\/agents\/[^/]+\/tasks(?:\?.*)?$/,r=>{
  if(r.request().method()==='POST'){const body=r.request().postDataJSON();state.writes.push({kind:'queue',body});if(state.failQueue)return json(r,{message:'تعذر الحفظ مؤقتًا؛ أعد المحاولة.'},503);const created=task({prompt:body.prompt,action:body.action});state.tasks=[created];return json(r,created,201);}
  return json(r,{items:new URL(r.request().url()).searchParams.has('cursor')?[task({state:'COMPLETED',result:'صفحة قديمة'})]:state.tasks,nextCursor:state.pages&&!new URL(r.request().url()).searchParams.has('cursor')?randomUUID():null});
 });
 await page.route('**/admin/agents/tasks/*/decision',r=>{const body=r.request().postDataJSON();state.writes.push({kind:'decision',body});state.tasks=state.tasks.map(t=>({...t,state:body.action==='CANCEL'?'CANCELLED':'REVIEWED',revision:randomUUID()}));return json(r,state.tasks[0]);});
 await page.route('**/admin/agents/tasks/*/governance-resume',r=>{expect(r.request().method()).toBe('POST');const body=r.request().postDataJSON(),id=new URL(r.request().url()).pathname.split('/').at(-2);state.writes.push({kind:'resume',body,id});if(state.failResume)return json(r,{message:'تغيرت الإحالة؛ حدّث البيانات وراجع الإجراء.'},409);if(state.badResume)return json(r,{id,resumed:'true',reviewTaskId:'invalid'},201);state.tasks=state.tasks.map(t=>t.id===id?{...t,governanceRouting:{status:'MANUAL_ROUTE_RESUMED',approved:false}}:t);return json(r,{id,reviewTaskId:randomUUID(),resumed:true},201);});
 await page.route('**/admin/agents/tasks/*/draft-correction',r=>{expect(r.request().method()).toBe('POST');const body=r.request().postDataJSON(),id=new URL(r.request().url()).pathname.split('/').at(-2);state.writes.push({kind:'correction',body,id});if(state.failCorrection)return json(r,{message:'التصحيح غير مأذون أو لا تتاح سعة في الطابور.'},409);if(state.badCorrection)return json(r,{id,correctionTaskId:'invalid'},201);state.tasks=state.tasks.map(t=>t.id===id?{...t,governanceRouting:{status:'DRAFT_CORRECTION_QUEUED',approved:false}}:t);return json(r,{id,correctionTaskId:randomUUID()},201);});
 await page.goto('/',{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>Boolean(window.HydrolandAdminAgentWorkforce&&window.HydrolandAuth&&window.HydrolandProfile));
 await page.evaluate(async()=>{window.HydrolandAuth.acceptSession({accessToken:'agent-browser-fixture',refreshToken:'agent-browser-refresh'},window.HydrolandAuth.beginAuthAttempt());await window.HydrolandProfile.load()});
 await openWorkspaceSwitcher(page);await page.locator('#role-dialog [data-role="admin"]').click();await expect(page.locator('.hl-role-dashboard[data-role="admin"]')).toBeVisible();if(await page.locator('[data-portal-menu]').isVisible())await page.locator('[data-portal-menu]').click();await page.locator('[data-portal-label="الذكاء الاصطناعي"]').click();await expect(page.locator('[data-agent-workforce]')).toHaveAttribute('open','');await expect(page.locator('[data-ai-feedback]')).toContainText('تم تحميل');return state;
}
const control=(page,key='INVENTORY')=>page.locator(`[data-ai-control][data-key="${key}"]`);
const review=async form=>{await form.locator('[name="reason"]').fill('قرار اختبار معزول بعد المراجعة');await form.locator('[name="reviewed"]').check();return form;};
