test('source snapshots survive periodic metric refresh but clear on read failure, explicit refresh and revocation',async({page})=>{
 await page.clock.install();const state=await setup(page);let reads=0;
 await page.route(/\/admin\/agents\/department-sources$/,r=>{reads++;return json(r,departmentSourceFixture());});
 const panel=page.locator('[data-ai-department-sources]'),status=page.locator('[data-ai-source-status]'),hr=page.locator('[data-ai-source-department="HR"]');
 await page.locator('[data-ai-source-check]').click();await expect(page.locator('[data-ai-source-department]')).toHaveCount(14);await hr.locator('summary').click();const captured=await status.textContent(),catalogReads=state.catalogReads;
 await page.clock.fastForward(16_000);await expect.poll(()=>state.catalogReads).toBeGreaterThan(catalogReads);await expect(page.locator('[data-ai-refresh]')).toBeEnabled();
 await expect(panel).toBeVisible();await expect(hr).toHaveAttribute('open','');await expect(status).toHaveText(captured);expect(reads).toBe(1);
 state.failCatalog=true;await page.clock.fastForward(16_000);await expect(panel).toBeHidden();await expect(page.locator('[data-ai-source-list]')).toBeEmpty();
 state.failCatalog=false;await expect(page.locator('[data-ai-refresh]')).toBeEnabled();await page.locator('[data-ai-source-check]').click();await expect(page.locator('[data-ai-source-department]')).toHaveCount(14);
 await page.locator('[data-ai-refresh]').click();await expect(panel).toBeHidden();await expect(page.locator('[data-ai-source-list]')).toBeEmpty();await expect(page.locator('[data-ai-refresh]')).toBeEnabled();
 await page.locator('[data-ai-source-check]').click();await expect(page.locator('[data-ai-source-department]')).toHaveCount(14);state.admin=false;await page.clock.fastForward(16_000);
 await expect(page.locator('#hl-admin-employees')).toBeHidden();await expect(page.locator('[data-ai-source-list]')).toBeEmpty();expect(reads).toBe(3);expect(state.writes).toHaveLength(0);expect(state.connectionChecks).toBe(0);
});
