test('per-agent control preserves conflict notes and resets acknowledgement when server revision changes',async({page})=>{
 const state=await setup(page,{failControl:true}),form=await review(control(page,'SUPPORT')),old=state.items[1].revision;await form.getByRole('button').click();await expect(form).toContainText('تغيرت الحالة');expect(state.writes[0]).toMatchObject({kind:'control',key:'SUPPORT',body:{state:'PAUSED',expectedRevision:old,reviewed:true,reason:'قرار اختبار معزول بعد المراجعة'}});
 state.items[1].revision=randomUUID();await page.locator('[data-ai-refresh]').click();await expect(form.getByRole('checkbox')).not.toBeChecked();await expect(form.locator('[name="reason"]')).toHaveValue('قرار اختبار معزول بعد المراجعة');state.failControl=false;await form.getByRole('checkbox').check();await form.getByRole('button').click();await expect(form.getByRole('button')).toHaveText('تشغيل الوكيل');expect(state.items[0].state).toBe('PAUSED');await page.locator('[data-ai-refresh]').click();await expect(form.getByRole('button')).toHaveText('تشغيل الوكيل');
});
