test('task review, cursor pages and model output remain safe on mobile and logout clears drafts',async({page})=>{
 await page.setViewportSize({width:390,height:844});const failed=task({state:'INTERRUPTED',result:'<img src=x onerror=alert(1)> مسودة',errorCode:'REVIEW_REQUIRED'}),state=await setup(page,{tasks:[failed],pages:true});await expect(page.locator('[data-ai-task-list] img')).toHaveCount(0);await expect(page.locator('[data-ai-task-list] pre')).toContainText('<img');const form=await review(page.locator('[data-ai-task-decision]'));await form.getByRole('button').click();await expect(page.locator('[data-ai-task-list]')).toContainText('رُوجع التعثر');expect(state.writes[0].body).toMatchObject({action:'ACKNOWLEDGE',expectedRevision:failed.revision,reviewed:true});await page.locator('[data-ai-older]').click();await expect(page.locator('[data-ai-task-list]')).toContainText('صفحة قديمة');await page.locator('[data-ai-newer]').click();await expect(page.locator('[data-ai-task-list]')).toContainText('رُوجع التعثر');expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.locator('[data-ai-task-form] [name="prompt"]').fill('مسودة قبل الخروج');await page.evaluate(()=>window.HydrolandAuth.logout());await expect(page.locator('[data-ai-task-list]')).toBeEmpty();await expect(page.locator('[data-ai-cards]')).toBeEmpty();await expect(page.locator('[data-ai-task-form] [name="prompt"]')).toHaveValue('');
});
